SELECT store_sales.product_id, COUNT(*) AS total_count, COUNT(DISTINCT inventory.quantity) AS unique_stores FROM inventory LEFT JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id WHERE store_sales.product_id IN (2, 7, 10) GROUP BY store_sales.product_id ORDER BY store_sales.product_id DESC, 2 DESC LIMIT 5
